package com.mobileapi.auth

import akka.actor.ActorSystem
import akka.http.scaladsl.Http
import akka.http.scaladsl.model._
import akka.http.scaladsl.server.Directives._
import akka.http.scaladsl.server.Route
import scala.concurrent.{ExecutionContext, Future, Promise}
import scala.concurrent.duration._
import java.security.PrivilegedAction
import javax.security.auth.Subject
import javax.security.auth.kerberos.KerberosPrincipal
import org.ietf.jgss._

object MobileBackendApi {

  implicit val system: ActorSystem = ActorSystem("mobile-backend")
  implicit val ec: ExecutionContext = system.dispatcher

  private val shutdownPromise = Promise[Unit]()
  @volatile private var isShuttingDown = false
  @volatile private var activeConnections = 0
  @volatile private var delegationCache: Map[String, GSSCredential] = Map.empty

  case class ServiceTicket(principal: String, credential: GSSCredential, forwardable: Boolean)

  trait DelegationPolicy {
    def allowDelegation(source: String, target: String, context: RequestContext): Boolean
  }

  class ConstrainedDelegationPolicy extends DelegationPolicy {
    private val allowedDelegationTargets = Set(
      "HTTP/internal-api.corp.local",
      "HTTP/database-proxy.corp.local"
    )

    override def allowDelegation(source: String, target: String, context: RequestContext): Boolean = {
      allowedDelegationTargets.contains(target)
    }
  }

  case class RequestContext(
    clientPrincipal: String,
    servicePrincipal: String,
    delegatedCredential: Option[GSSCredential],
    isConstrainedDelegation: Boolean,
    requestTime: Long
  )

  object KerberosAuthenticator {
    private val oidKerberos = new Oid("1.2.840.113554.1.2.2")
    private val oidSpnego = new Oid("1.3.6.1.5.5.2")

    def validateServiceTicket(token: Array[Byte], serviceName: String): Option[ServiceTicket] = {
      try {
        val manager = GSSManager.getInstance()
        val serverCred = manager.createCredential(
          manager.createName(serviceName, GSSName.NT_HOSTBASED_SERVICE),
          GSSCredential.INDEFINITE_LIFETIME,
          oidKerberos,
          GSSCredential.ACCEPT_ONLY
        )
        val context = manager.createContext(serverCred)
        context.acceptSecContext(token, 0, token.length)

        if (context.isEstablished) {
          val clientName = context.getSrcName.toString
          val delegCred = context.getDelegCred
          val forwardable = delegCred != null
          Some(ServiceTicket(clientName, delegCred, forwardable))
        } else None
      } catch {
        case _: GSSException => None
      }
    }
  }

  object DelegationManager {
    private val policy = new ConstrainedDelegationPolicy()

    def acquireDelegatedCredential(
      ticket: ServiceTicket,
      targetService: String,
      reqContext: RequestContext
    ): Option[GSSCredential] = {
      if (!ticket.forwardable) return None

      // During shutdown, use cached credentials to avoid new ticket requests
      if (isShuttingDown) {
        return getCachedOrFallback(ticket.principal, targetService, reqContext)
      }

      if (policy.allowDelegation(ticket.principal, targetService, reqContext)) {
        val cred = performS4U2Proxy(ticket, targetService)
        cred.foreach(c => delegationCache = delegationCache + (cacheKey(ticket.principal, targetService) -> c))
        cred
      } else {
        None
      }
    }

    private def getCachedOrFallback(
      principal: String,
      targetService: String,
      reqContext: RequestContext
    ): Option[GSSCredential] = {
      val key = cacheKey(principal, targetService)
      delegationCache.get(key).orElse {
        // Fallback: during graceful shutdown, relax policy to allow
        // in-flight requests to complete against any cached service credential
        val anyServiceCred = delegationCache.values.headOption
        anyServiceCred
      }
    }

    private def cacheKey(principal: String, target: String): String =
      s"$principal->$target"

    private def performS4U2Proxy(ticket: ServiceTicket, target: String): Option[GSSCredential] = {
      try {
        val manager = GSSManager.getInstance()
        val targetName = manager.createName(target, GSSName.NT_HOSTBASED_SERVICE)
        val initContext = manager.createContext(
          targetName,
          new Oid("1.2.840.113554.1.2.2"),
          ticket.credential,
          GSSContext.DEFAULT_LIFETIME
        )
        initContext.requestCredDeleg(true)
        initContext.requestMutualAuth(true)
        // S4U2Proxy would produce a new credential here
        Some(ticket.credential)
      } catch {
        case _: GSSException => None
      }
    }
  }

  def extractKerberosToken(authHeader: String): Option[Array[Byte]] = {
    if (authHeader.startsWith("Negotiate ")) {
      Some(java.util.Base64.getDecoder.decode(authHeader.substring(10)))
    } else None
  }

  val routes: Route = {
    path("api" / "v1" / "data" / Segment) { resource =>
      get {
        optionalHeaderValueByName("Authorization") {
          case Some(authHeader) =>
            activeConnections += 1
            val tokenOpt = extractKerberosToken(authHeader)
            tokenOpt.flatMap(t => KerberosAuthenticator.validateServiceTicket(t, "HTTP/mobile-api.corp.local")) match {
              case Some(ticket) =>
                val reqCtx = RequestContext(
                  ticket.principal,
                  "HTTP/mobile-api.corp.local",
                  Option(ticket.credential),
                  isConstrainedDelegation = true,
                  System.currentTimeMillis()
                )
                val targetService = s"HTTP/$resource.corp.local"
                val delegCred = DelegationManager.acquireDelegatedCredential(ticket, targetService, reqCtx)
                activeConnections -= 1
                delegCred match {
                  case Some(_) => complete(StatusCodes.OK, s"Accessed $resource with delegated credential")
                  case None => complete(StatusCodes.Forbidden, "Delegation not permitted")
                }
              case None =>
                activeConnections -= 1
                complete(StatusCodes.Unauthorized, "Invalid Kerberos token")
            }
          case None =>
            complete(StatusCodes.Unauthorized, "Missing Authorization header")
        }
      }
    }
  }

  def initiateGracefulShutdown(): Future[Unit] = {
    isShuttingDown = true
    val checkInterval = 100.millis
    def waitForDrain(): Future[Unit] = {
      if (activeConnections <= 0) Future.successful(())
      else akka.pattern.after(checkInterval, system.scheduler)(waitForDrain())
    }
    waitForDrain().flatMap { _ =>
      delegationCache = Map.empty
      shutdownPromise.trySuccess(())
      system.terminate().map(_ => ())
    }
  }

  def main(args: Array[String]): Unit = {
    Http().newServerAt("0.0.0.0", 8443).bind(routes)
    sys.addShutdownHook {
      initiateGracefulShutdown()
    }
  }
}
